9	import type { UpdateProfileInput } from "@/schemas/member";
10	import type { UserId } from "@/types/common";
11	import type { User } from "@/types/member";
12	
13	export async function findUserById(userId: UserId): Promise<User | null> {
14	  const rows = getDb().select().from(users).where(eq(users.id, userId)).all();
15	  const row = rows.at(0);
16	  return row ? toUser(row) : null;
17	}
18	
19	export async function findUserByEmail(email: string): Promise<User | null> {
20	  const rows = getDb()
21	    .select()
22	    .from(users)
23	    .where(eq(users.email, email.toLowerCase()))
24	    .all();
25	  const row = rows.at(0);
26	  return row ? toUser(row) : null;
27	}
28	
29	export async function insertUser(input: {
30	  email: string;
31	  name: string;
32	  passwordHash: string;
33	}): Promise<User> {
34	  const stamp = toIsoTimestamp(new Date());
35	  const row = getDb()
36	    .insert(users)
37	    .values({
38	      id: newId(),
39	      email: input.email.toLowerCase(),
40	      name: input.name,
41	      passwordHash: input.passwordHash,
42	      avatarUrl: null,
43	      timezone: "UTC",
44	      emailVerifiedAt: null,
45	      createdAt: stamp,
